'use client';

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import ChatInterface from './components/ChatInterface';
import ThemeToggle from './components/ThemeToggle';

interface Message {
  role: string;
  content: string;
  timestamp?: string;
  components?: any[];
}

interface Chat {
  id: string;
  title: string;
  messages: Message[];
  lastUpdated: string;
}

export default function Home() {
  const [chats, setChats] = useState<Chat[]>([]);
  const [currentChatId, setCurrentChatId] = useState<string | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);

  // Load theme from localStorage
  useEffect(() => {
    const savedTheme = localStorage.getItem('theme');
    const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
    setIsDarkMode(savedTheme === 'dark' || (!savedTheme && prefersDark));
  }, []);

  // Apply theme to document
  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    localStorage.setItem('theme', isDarkMode ? 'dark' : 'light');
  }, [isDarkMode]);

  // Load chats from localStorage
  useEffect(() => {
    const savedChats = localStorage.getItem('chats');
    if (savedChats) {
      const parsedChats = JSON.parse(savedChats);
      setChats(parsedChats);
      if (parsedChats.length > 0) {
        setCurrentChatId(parsedChats[0].id);
        setMessages(parsedChats[0].messages);
      }
    }
  }, []);

  // Save chats to localStorage
  useEffect(() => {
    if (chats.length > 0) {
      localStorage.setItem('chats', JSON.stringify(chats));
    }
  }, [chats]);

  const generateChatId = () => {
    return 'chat_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
  };

  const createNewChat = () => {
    const newChatId = generateChatId();
    const newChat: Chat = {
      id: newChatId,
      title: '',
      messages: [],
      lastUpdated: new Date().toISOString(),
    };
    
    setChats(prev => [newChat, ...prev]);
    setCurrentChatId(newChatId);
    setMessages([]);
  };

  const selectChat = (chatId: string) => {
    const chat = chats.find(c => c.id === chatId);
    if (chat) {
      setCurrentChatId(chatId);
      setMessages(chat.messages);
    }
  };

  const deleteChat = (chatId: string) => {
    setChats(prev => prev.filter(c => c.id !== chatId));
    
    if (currentChatId === chatId) {
      const remainingChats = chats.filter(c => c.id !== chatId);
      if (remainingChats.length > 0) {
        setCurrentChatId(remainingChats[0].id);
        setMessages(remainingChats[0].messages);
      } else {
        setCurrentChatId(null);
        setMessages([]);
      }
    }
  };

  const updateCurrentChat = (newMessages: Message[]) => {
    if (!currentChatId) return;

    setChats(prev => prev.map(chat => {
      if (chat.id === currentChatId) {
        return {
          ...chat,
          messages: newMessages,
          lastUpdated: new Date().toISOString(),
          title: chat.title || (newMessages.find(m => m.role === 'user')?.content.slice(0, 30) + '...' || 'New Chat')
        };
      }
      return chat;
    }));
  };

  const parseComponentsFromText = (text: string): { cleanText: string; components: any[] } => {
    const components: any[] = [];
    let cleanText = text;

    // Look for JSON components in the text
    const jsonRegex = /```json\s*(\{[\s\S]*?\})\s*```/g;
    let match;

    while ((match = jsonRegex.exec(text)) !== null) {
      try {
        const jsonData = JSON.parse(match[1]);
        if (jsonData.component) {
          components.push(jsonData.component);
          cleanText = cleanText.replace(match[0], '').trim();
        }
      } catch (error) {
        console.error('Error parsing JSON component:', error);
      }
    }

    return { cleanText, components };
  };

  const sendMessage = async (content: string) => {
    if (!content.trim()) return;

    // Create new chat if none exists
    if (!currentChatId) {
      createNewChat();
      // Wait a bit for state to update
      await new Promise(resolve => setTimeout(resolve, 100));
    }

    const userMessage: Message = {
      role: 'user',
      content,
      timestamp: new Date().toISOString(),
    };

    const newMessages = [...messages, userMessage];
    setMessages(newMessages);
    setIsLoading(true);

    try {
      const response = await fetch('http://localhost:8000/chat/stream', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          messages: newMessages.map(m => ({ role: m.role, content: m.content })),
          use_web_search: true,
          enable_components: true,
        }),
      });

      if (!response.body) {
        throw new Error('No response body');
      }

      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let assistantContent = '';

      while (true) {
        const { value, done } = await reader.read();
        if (done) break;

        const chunk = decoder.decode(value);
        const lines = chunk.split('\n');

        for (const line of lines) {
          if (line.startsWith('data: ')) {
            try {
              const data = JSON.parse(line.slice(6));
              
              if (data.content) {
                assistantContent += data.content;
                
                // Update messages with current content
                const assistantMessage: Message = {
                  role: 'assistant',
                  content: assistantContent,
                  timestamp: new Date().toISOString(),
                };
                
                const updatedMessages = [...newMessages, assistantMessage];
                setMessages(updatedMessages);
              }
              
              if (data.done) {
                // Parse components from final content
                const { cleanText, components } = parseComponentsFromText(assistantContent);
                
                const finalAssistantMessage: Message = {
                  role: 'assistant',
                  content: cleanText,
                  timestamp: new Date().toISOString(),
                  components: components.length > 0 ? components : undefined,
                };
                
                const finalMessages = [...newMessages, finalAssistantMessage];
                setMessages(finalMessages);
                updateCurrentChat(finalMessages);
                break;
              }
              
              if (data.error) {
                throw new Error(data.error);
              }
            } catch (error) {
              console.error('Error parsing SSE data:', error);
            }
          }
        }
      }
    } catch (error) {
      console.error('Error sending message:', error);
      const errorMessage: Message = {
        role: 'assistant',
        content: 'Sorry, I encountered an error while processing your request. Please make sure the backend server is running.',
        timestamp: new Date().toISOString(),
      };
      
      const errorMessages = [...newMessages, errorMessage];
      setMessages(errorMessages);
      updateCurrentChat(errorMessages);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex h-screen bg-gray-50 dark:bg-gray-900">
      {/* Sidebar */}
      <Sidebar
        chats={chats}
        currentChatId={currentChatId}
        isCollapsed={isSidebarCollapsed}
        onToggleCollapse={() => setIsSidebarCollapsed(!isSidebarCollapsed)}
        onSelectChat={selectChat}
        onNewChat={createNewChat}
        onDeleteChat={deleteChat}
      />

      {/* Main Content */}
      <div className="flex-1 flex flex-col">
        {/* Top Bar */}
        <div className="bg-white dark:bg-gray-900 border-b border-gray-200 dark:border-gray-700 p-4 flex justify-end">
          <ThemeToggle isDarkMode={isDarkMode} onToggle={() => setIsDarkMode(!isDarkMode)} />
        </div>

        {/* Chat Interface */}
        <div className="flex-1">
          <ChatInterface
            messages={messages}
            onSendMessage={sendMessage}
            isLoading={isLoading}
            isDarkMode={isDarkMode}
          />
        </div>
      </div>
    </div>
  );
}
